package main

type ShoppingCart struct {
    items map[string]int
    prices map[string]float64
}

func NewShoppingCart() *ShoppingCart {
    return &ShoppingCart{
        items: make(map[string]int),
        prices: make(map[string]float64),
    }
}

func (c *ShoppingCart) AddItem(name string, price float64) {
    c.items[name]++
    c.prices[name] = price
}

func (c *ShoppingCart) RemoveItem(name string) {
    if count, exists := c.items[name]; exists && count > 0 {
        c.items[name]--
        if c.items[name] == 0 {
            delete(c.items, name)
            delete(c.prices, name)
        }
    }
}

func (c *ShoppingCart) GetTotal() float64 {
    total := 0.0
    for name, count := range c.items {
        total += c.prices[name] * float64(count)
    }
    return total
}

func (c *ShoppingCart) GetItemCount() int {
    count := 0
    for _, quantity := range c.items {
        count += quantity
    }
    return count
}

func (c *ShoppingCart) Clear() {
    c.items = make(map[string]int)
    c.prices = make(map[string]float64)
}
```

